import {useFeatureAppEnv, useSalesChannel} from '@smart/feature-app';
import {getBaseSiteId, getLanguage} from '@smart/locale-service';
import {Flex, Text} from '@smart/react-components';
import React from 'react';
import {useTranslations} from '../../../feature-app/hooks';
import {ROUTE} from '../../constants/common';
import {useAppModelContext} from '../../hooks/use-app-model';
import {useLocale} from '../../hooks/use-locale';
import {updatePcpLoadingState} from '../../hooks/use-pcp-loading-state';
import {usePostOrderPcp} from '../../hooks/use-post-order-pcp';
import {useOnceEffect} from '../../hooks/useOnceEffect';
import {initialize} from '../../utils/initialize-iframe';
import styles from './index.module.scss';

// Declare the global integration object from the external script
declare global {
  interface Window {
    integration: {
      initialize: (options: any) => Promise<{
        on: (event: string, callback: (event: any) => void) => void;
        isActive: () => boolean;
        isValid: () => boolean;
        createToken: (callback: (error: any, response: any) => void) => void;
      }>;
    };
  }
}

const baseClass = `pcp-payment-iframe`;

const PcpPaymentIframe = () => {
  const {
    baseUrl,
    featureServices: {
      's2:history': {history},
      'endpoint-directory': endpointDirectory,
    },
  } = useFeatureAppEnv();
  const {marketId, languageTag} = useLocale();
  const language = getLanguage(languageTag);
  const baseSiteId = getBaseSiteId(marketId);
  const {appContextData, setAppContextData} = useAppModelContext();
  const {
    cartModel: {cartId},
  } = appContextData as any;
  const {submitOrder} = usePostOrderPcp();

  const salesChannel = useSalesChannel();

  const {t} = useTranslations();

  useOnceEffect(() => {
    void fetchData();
  }, []);

  const fetchData = async () => {
    let userIpAddress = ``;

    try {
      // Fetch IP address
      const ipResponse = await fetch(`https://api.ipify.org?format=json`);
      const ipData = await ipResponse.json();
      userIpAddress = ipData.ip;
    } catch (error) {
      console.error(`Error fetching IP address:`, error);
      // Continue with empty IP address
    }

    const deviceInformation = {
      http_browser_screen_width: window.screen.width.toString(),
      http_browser_screen_height: window.screen.height.toString(),
      ip_address: userIpAddress,
    };

    const initializeOptions = {
      baseSiteId,
      cartId,
      marketId,
      language,
      languageTag,
      salesChannel,
      endpointDirectory,
      deviceInformation,
    };

    const res = await initialize(baseUrl, initializeOptions);

    const {
      client_session: clientSession,
      client_configuration: clientConfiguration,
    } = res;

    if (clientSession && clientConfiguration) {
      initializeIFrame(clientSession, clientConfiguration);
    }
  };

  var formStyles = {
    'input': {
      'font-size': `16px`,
      'color': `#141413`,
      'line-height': `140%`,
    },
    '.ifs-valid': {
      color: `#141413`,
    },
    '.ifs-invalid': {
      color: `red`,
    },
    '.ifs-not-accepted': {
      color: `DarkGoldenRod`,
    },
  };

  const initializeIFrame: (
    clientSession: string,
    clientConfiguration: string,
  ) => void = (clientSession, clientConfiguration) => {
    const options = {
      clientSession,
      clientConfiguration,
      type: `creditCard`, // Payment method type
      fields: {
        holder: {
          selector: `#iframeCardholder`,
          placeholder: t(`pcp.iframe.placeholder.nameOnCard`),
          required: false,
        },
        number: {
          selector: `#iframePan`,
          placeholder: t(`pcp.iframe.placeholder.cardNumber`),
        },
        code: {
          selector: `#iframeCvc`,
          placeholder: t(`pcp.iframe.placeholder.cvc`),
        },
        expiry: {
          selector: `#iframeExpiry`,
          placeholder: t(`pcp.iframe.placeholder.expiry`),
        },
      },
      styles: formStyles,
    };

    window.integration
      .initialize(options)
      .then(function (ifsInstance: {
        createToken: any;
        on: (arg0: string, arg1: (event: any) => void) => void;
        isActive: () => any;
        isValid: () => any;
      }) {
        console.info(`iFrame initialized successfully.`);

        // Enable the submit button once the form is valid
        ifsInstance.on(`formValidationChange`, function (event: any) {
          const submitButton = document.getElementById(`submitButton`);
          if (submitButton) {
            if (event.valid && event.completed) {
              submitButton.removeAttribute(`disabled`);
            } else {
              submitButton.setAttribute(`disabled`, `true`);
            }
          }
        });

        const paymentForm = document.getElementById(`paymentForm`);
        if (paymentForm) {
          paymentForm.addEventListener(`submit`, function (event) {
            // Prevent default form submission
            event.preventDefault();

            // Validate the form and create token
            if (!ifsInstance.isActive() || !ifsInstance.isValid()) {
              console.error(
                `Form is invalid! Please fill in all required fields.`,
              );
              return;
            }

            // Mark as loading
            updatePcpLoadingState(true);

            // Create token for the payment
            ifsInstance.createToken(async function (error: any, response: any) {
              if (error) {
                console.error(`Error creating token:`, error);
                updatePcpLoadingState(false);
                return;
              }

              console.info(`Token generated:`, response);

              try {
                const orderResponse = await submitOrder(cartId, response.token);
                console.info(`payment successful`, orderResponse);
                if (orderResponse.code === `200`) {
                  history.push(
                    `/${ROUTE.ORDER_SUCCESS}?orderId=${orderResponse.orderCode}`,
                  );
                } else {
                  setAppContextData((prevData) => {
                    if (prevData?.cartModel) {
                      return {
                        ...prevData,
                        cartModel: {
                          ...prevData.cartModel,
                          pcpPaymentResponse: orderResponse,
                        },
                      };
                    }
                    return prevData;
                  });
                }
              } catch (otpError) {
                console.error(`payment failed`, otpError);
              } finally {
                updatePcpLoadingState(false);
              }
            });
          });
        }
      })
      .catch(function (err: any) {
        console.error(`iFrame initialization failed:`, err);
      });
  };

  return (
    <div className={styles[`${baseClass}`]}>
      <div className={styles[`${baseClass}__header`]}>
        <Text
          variant="p-100"
          color="c-high-contrast"
          className={styles[`${baseClass}__title`]}
        >
          {t(`pcp.iframe.cardPayment`)}
        </Text>
        <div className={styles[`${baseClass}__icons`]}>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="50"
            height="30"
            viewBox="0 0 50 30"
            fill="none"
          >
            <rect x="0.5" y="0.5" width="49" height="29" fill="white" />
            <rect x="0.5" y="0.5" width="49" height="29" stroke="#DADADA" />
            <path
              d="M31.0683 9C28.2212 9 25.6769 10.363 25.6769 12.8813C25.6769 15.7693 30.1893 15.9688 30.1893 17.4197C30.1893 18.0305 29.4314 18.5774 28.1368 18.5774C26.2996 18.5774 24.9264 17.8133 24.9264 17.8133L24.3389 20.3546C24.3389 20.3546 25.9207 21 28.0209 21C31.1337 21 33.583 19.57 33.583 17.0087C33.583 13.957 29.0519 13.7634 29.0519 12.4168C29.0519 11.9382 29.674 11.4139 30.9649 11.4139C32.4214 11.4139 33.6097 11.9696 33.6097 11.9696L34.1847 9.51521C34.1847 9.51521 32.8917 9 31.0683 9ZM5.02013 9.18525L4.95117 9.55573C4.95117 9.55573 6.14897 9.75818 7.22775 10.1621C8.61677 10.6252 8.71575 10.8948 8.94967 11.7323L11.4988 20.809H14.9161L20.1806 9.18525H16.7712L13.3884 17.0883L12.0081 10.3893C11.8815 9.62261 11.2403 9.18525 10.4554 9.18525H5.02013ZM21.5515 9.18525L18.877 20.8089H22.1281L24.7933 9.18522H21.5515V9.18525ZM39.6842 9.18525C38.9002 9.18525 38.4849 9.57293 38.1801 10.2504L33.4169 20.8089H36.8263L37.486 19.0491H41.6396L42.0407 20.8089H45.049L42.4245 9.18525H39.6842ZM40.1276 12.3256L41.1382 16.6874H38.4307L40.1276 12.3256Z"
              fill="#1434CB"
            />
          </svg>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="50"
            height="30"
            viewBox="0 0 50 30"
            fill="none"
          >
            <rect x="0.5" y="0.5" width="49" height="29" fill="white" />
            <rect x="0.5" y="0.5" width="49" height="29" stroke="#DADADA" />
            <path
              d="M43.0031 15.0001C43.0031 20.8982 38.0175 25.676 31.8688 25.676C25.72 25.676 20.7344 20.8982 20.7344 15.0001C20.7344 9.10203 25.7123 4.32422 31.861 4.32422C38.0097 4.32422 43.0031 9.10203 43.0031 15.0001Z"
              fill="#F79F1A"
            />
            <path
              d="M29.2727 15.0001C29.2727 20.8982 24.287 25.676 18.1383 25.676C11.9896 25.676 7.00391 20.8982 7.00391 15.0001C7.00391 9.10203 11.9896 4.32422 18.1383 4.32422C24.287 4.32422 29.2727 9.10203 29.2727 15.0001Z"
              fill="#EA001B"
            />
            <path
              d="M24.9989 6.59375C22.4014 8.54494 20.7344 11.5867 20.7344 14.9994C20.7344 18.4122 22.4014 21.4539 24.9989 23.4051C27.5964 21.4539 29.2635 18.4122 29.2635 14.9994C29.2635 11.5867 27.5964 8.55236 24.9989 6.59375Z"
              fill="#FF5F01"
            />
          </svg>
        </div>
      </div>

      <form id="paymentForm" className={styles[`${baseClass}__form`]}>
        <div className={styles[`${baseClass}__form-group`]}>
          <label htmlFor="iframeCardholder">
            {t(`pcp.iframe.label.nameOnCard`)}
          </label>
          <div
            id="iframeCardholder"
            style={{borderBottom: `1px solid #000`}}
          ></div>
        </div>

        <div className={styles[`${baseClass}__form-group`]}>
          <label htmlFor="iframePan">{t(`pcp.iframe.label.cardNumber`)}</label>
          <div id="iframePan" style={{borderBottom: `1px solid #000`}}></div>
        </div>

        <Flex gap={200} justifyContent={`space-between`}>
          <div className={styles[`${baseClass}__form-group`]} style={{flex: 1}}>
            <label htmlFor="iframeExpiry">
              {t(`pcp.iframe.label.expiryDate`)}
            </label>
            <div
              id="iframeExpiry"
              style={{borderBottom: `1px solid #000`}}
            ></div>
          </div>

          <div className={styles[`${baseClass}__form-group`]} style={{flex: 1}}>
            <label htmlFor="iframeCvc">{t(`pcp.iframe.label.cvc`)}</label>
            <div id="iframeCvc" style={{borderBottom: `1px solid #000`}}></div>
          </div>
        </Flex>
      </form>
    </div>
  );
};

export default PcpPaymentIframe;

