import {useSalesChannel} from '@smart/feature-app/react';
import {useTranslations} from '@smart/react-utils';
import {MARKET, PAYMENT_MODE, PAYMENT_TYPE, SalesChannel} from '@smart/types';
import {isGlobalFeatureFlagsEnabled} from '@smart/utils';
import {Notification} from '@smart/web-components';
import React, {useEffect, useState} from 'react';
import {FEATURE_FLAGS} from '../../../../types/common.types';
import type {AppModel} from '../../../bff/app-model/create-content-model';
import {useCurrentConditions} from '../../../feature-app/contexts/pages/get-current-conditions';
import {DepositContainer} from '../../components/cart-details/deposit-container/deposit-container';
import {ErrorMessage} from '../../components/error/error-message';
import {LoadingPage} from '../../components/loader';
import {ButtonsRow} from '../../components/order-overview/buttons-row';
import {Notifications} from '../../components/order-overview/notifications';
import {OrderDetails} from '../../components/order-overview/order-details';
import {PaymentSummary} from '../../components/order-overview/payment-summary';
import {TermsConditions} from '../../components/order-overview/terms-conditions';
import {OrderSummary} from '../../components/order-summary/order-summary';
import {
  CART_STATUS,
  ROUTE,
  orderOverviewBaseClass,
} from '../../constants/common';
import {createSpecificPpoImageUrl} from '../../constants/dam-files-path';
import {
  LeasingOrderConflictError,
  StockReservePeriodExpiredError,
} from '../../errors';
import {
  EventType,
  type IDeliveryMethod,
  type IEventDataConfirmation,
  useAppModelContext,
  useFeatureAppEnv,
  useLocale,
  useTracking,
  useUserModelContext,
} from '../../hooks';
import {useAemModelContext} from '../../hooks/use-aem-model';
import {useCartStatus} from '../../hooks/use-cart-status';
import {useCheckoutContext} from '../../hooks/use-checkout-context';
import {useIDealPaymentPayload} from '../../hooks/use-ideal-payment-payload';
import {useRedirectOnMissingBankIDVerification} from '../../hooks/use-redirect-on-missing-bankid-verification';
import {useTrackingDelivery} from '../../hooks/use-tracking-delivery';
import {cleanAnalyticsData, postOrderOverviewModel} from '../../utils';
import {MOCKED_VALUES} from '../../utils/mocked-values-local-storage';
import {processIDealPayment} from '../../utils/process-ideal-payment';
import {crossBorderValidation} from '../personal-details/index.utils';
import styles from './index.module.scss';
import {PAYMENT_MODE_CODES} from './index.types';
import {createLeasingPayload} from './index.utils';
import {useOrderError} from './useOrderError';

export type OrderOverviewOptions = {
  setApiErrorInStepper: (apiError: boolean) => void;
};

const PAYMENT_FLOWS = {
  DEFAULT: `DEFAULT`,
  IDEAL: `IDEAL`,
  SUBSIDIES: `SUBSIDIES`,
} as const;

type PaymentFlowHandler = Partial<
  Record<keyof typeof PAYMENT_FLOWS, () => Promise<void> | void>
>;

// eslint-disable-next-line complexity
export const OrderOverview = ({
  setApiErrorInStepper,
}: OrderOverviewOptions): JSX.Element => {
  const iDealPayload = useIDealPaymentPayload();
  const currentConditions = useCurrentConditions();

  const {setShowStepper} = useCheckoutContext();

  const [loading, setLoading] = useState<boolean>(false);

  const orderError = useOrderError();
  const [showPCPErrorNotific, setShowPCPErrorNotific] = useState<boolean>(true);
  const {marketId, languageTag} = useLocale();
  const [failedPayment, setFailedPayment] = useState<Boolean>(false);
  const [isPaymentModeStatusUpdating, setPaymentModeStatusUpdating] =
    useState<boolean>(false);

  const {postCartStatus} = useCartStatus();
  const {
    baseUrl,
    featureServices: {
      's2:history': {history},
      'endpoint-directory': endpointDirectory,
    },
  } = useFeatureAppEnv();
  const {
    userModel: {userData},
  } = useUserModelContext();
  const {aemModel} = useAemModelContext();
  const {appContextData, setAppContextData} = useAppModelContext();
  const {
    aemContent: {translations, shoppingCart, imageURL},
  } = aemModel!;
  const {
    cartModel: {
      aldSalesChannel,
      activePaymentMode,
      paymentFailed,
      cartId,
      paymentModes,
      cartStatus,
      products: {
        vehicles: [vehicleDetails],
      },
      addresses: {paymentAddress, shippingAddress},
      prices: {totalPriceWithTax},
      analyticsData,
      paymentData,
      pcpPaymentResponse,
    },
    isMockEnabledFunc,
  } = appContextData as AppModel;

  const {paymentModes: availablePaymentModes} = paymentModes || {};
  const {voucher, paymentTypeData} = paymentData || {};
  const {paymentType, paymentTypeMap} = paymentTypeData || {};
  const {isLeasing, isCashBuy} = paymentTypeMap || {}!;

  if (!paymentType) {
    throw new Error(`paymentType is undefined`);
  }

  const isIDealPaymentMode = currentConditions.includes(`ideal`);

  useEffect(() => {
    const handlePageShow = function (event: PageTransitionEvent) {
      if (event.persisted && isIDealPaymentMode && paymentType === `CASHBUY`) {
        // unfreeze cart
        void postCartStatus({
          cartStatus: CART_STATUS.CREATED,
        });
        setLoading(false);
      }
    };

    window.addEventListener(`pageshow`, handlePageShow);

    return () => {
      window.removeEventListener(`pageshow`, handlePageShow);
    };
  }, []);

  // FEATURE FLAGS
  const isLoaEnabled = marketId.toUpperCase() === MARKET.FR;

  const isIDealEnabled = marketId.toUpperCase() === MARKET.NL;

  const isIDealPaymentMockEnabled = isMockEnabledFunc?.(
    MOCKED_VALUES.MOCKED_IDEAL_PAYMENT,
  );

  const salesChannel = useSalesChannel();

  const [isTermsAndConditionsValid, setIsTermsAndConditionsValid] =
    useState<boolean>(false);
  const modAnalyticsData = cleanAnalyticsData(analyticsData);
  const [extendDataLayer] = useTracking<
    IDeliveryMethod | IEventDataConfirmation
  >();
  const preferredAgentDetails: any = vehicleDetails?.dealerData; //temp until ecom returns name and email

  useRedirectOnMissingBankIDVerification();

  const isSubsidiesEnabled = isGlobalFeatureFlagsEnabled(
    FEATURE_FLAGS.SUBSIDIES,
    marketId,
  );
  const subsidiesDepositAmount =
    isSubsidiesEnabled && !currentConditions.includes(`leasing`)
      ? vehicleDetails?.depositAmount
      : undefined;

  const disabledByAgentLeasingCheck =
    !shoppingCart.isAgentAllowedInLeasingFlag &&
    currentConditions.includes(`adb`) &&
    currentConditions.includes(`leasing`);

  //only one condition for now but in the future there can be more, so moved it to a separate variable

  let paymentModesFiltered = availablePaymentModes?.filter((mode) =>
    isLoaEnabled ? mode.code : mode.code === PAYMENT_MODE_CODES.BANK_PAYMENT,
  );

  // For buying wallbox after successful ALD flow for mixed cart - SDI-3437
  if (!paymentModesFiltered) {
    paymentModesFiltered = [{code: PAYMENT_MODE_CODES.BANK_PAYMENT}];
  }

  // NOTE: this is a temporary solution to hide iDEAL for now
  isIDealEnabled &&
    !currentConditions.includes(`leasing`) &&
    salesChannel !== SalesChannel.DEMO &&
    paymentModesFiltered?.push({code: PAYMENT_MODE_CODES.IDEAL});

  useEffect(() => {
    setShowStepper(true);
    // If there is a separate paymentType for deposit we add it to session for analytics
    const isDepositOrder = subsidiesDepositAmount;

    if (isDepositOrder) {
      sessionStorage.setItem(`smart-deposit_payment_option`, activePaymentMode);
    } else {
      sessionStorage.removeItem(`smart-deposit_payment_option`);
    }
  }, [activePaymentMode, subsidiesDepositAmount]);

  useEffect(() => {
    if (paymentFailed) {
      setFailedPayment(true);
    }
    setAppContextData((prevData) => {
      if (prevData?.cartModel) {
        return {
          ...prevData,
          cartModel: {
            ...prevData.cartModel,
            paymentFailed: false,
          },
        };
      }
      return prevData;
    });
  }, []);

  const postOrderOverviewModelAndHandle = async () => {
    try {
      const result = await postOrderOverviewModel(baseUrl, {
        languageTag,
        salesChannel,
        cartId,
        marketId,
        endpointDirectory,
        isSme: userData.profile?.isSme,
        paymentMode: isLeasing ? undefined : activePaymentMode,
        paymentType,
        salesType: aldSalesChannel,
        leasing: isLeasing
          ? createLeasingPayload({
              userData,
              vehicleDetails: vehicleDetails!,
              preferredAgentDetails,
              orderOverviewUrl: createSpecificPpoImageUrl({
                aemImageURL: imageURL,
                pn18: vehicleDetails!.pn18,
                params: {
                  wid: 1024,
                  hei: 512,
                },
                model: vehicleDetails?.modelCode || ``,
              }),
              paymentAddress,
              paymentTypeMap,
            })
          : undefined,
      });

      if (isLeasing && `redirect_url` in result && result.redirect_url) {
        const webTrackObj: IEventDataConfirmation = {
          type: `navigation`,
          region: `checkout`,
          name: `confirmation`,
          transaction: {
            value: totalPriceWithTax,
            orderId: cartId,
            voucher: voucher?.code,
            ...(vehicleDetails && {
              outlet: [
                {
                  id: vehicleDetails?.dealerData?.uid || `n/a`,
                  name: vehicleDetails?.dealerData?.name || `n/a`,
                },
              ],
            }),
            product: modAnalyticsData.filter(
              (product) => product.type === `VEHICLE`,
            ),
          },
        };

        extendDataLayer(webTrackObj, EventType.CLICK);
        setTimeout(() => {
          window.open(result.redirect_url, `_parent`);
        }, 500);
      }

      if (!isLeasing && `orderData` in result) {
        setLoading(false);
        setAppContextData((prevData) => {
          return {
            ...prevData,
            orderData: result.orderData,
            cartModel: result.cartData,
          };
        });
        history.push(
          `/${ROUTE.ORDER_SUCCESS}?orderId=${result.orderData[0]?.transaction?.orderId}`,
        );
      }
    } catch (error: any) {
      orderError.handle(error);
      setLoading(false);
      setApiErrorInStepper(true);
    }
  };

  const defaultPaymentFlow = async () => {
    await postOrderOverviewModelAndHandle();
  };
  const idealPaymentFlow = async () => {
    try {
      const result = await processIDealPayment(iDealPayload, salesChannel);
      // freeze cart and update cart status
      await postCartStatus({
        cartStatus: CART_STATUS.IDEAL_PAYMENT_PENDING,
      });

      if (isIDealPaymentMockEnabled) {
        history.push({
          pathname: `/${ROUTE.MOCKED_PAYMENT_GATEWAY}`,
        });
        return;
      }

      window.location.href = result.redirectUrl;
    } catch (error: any) {
      setLoading(false);
      setFailedPayment(true);
      throw Error(error.message);
    }
  };

  const paymentFlows: Record<PAYMENT_TYPE, PaymentFlowHandler> = {
    [PAYMENT_TYPE.CASH]: {
      [PAYMENT_FLOWS.IDEAL]: idealPaymentFlow,
      [PAYMENT_FLOWS.SUBSIDIES]: () => {
        history.push(ROUTE.PAYMENT);
      },
      [PAYMENT_FLOWS.DEFAULT]: defaultPaymentFlow,
    },
    [PAYMENT_TYPE.LEASING]: {
      [PAYMENT_FLOWS.DEFAULT]: defaultPaymentFlow,
    },
    [PAYMENT_TYPE.FINANCE]: {
      [PAYMENT_FLOWS.DEFAULT]: defaultPaymentFlow,
    },
  };
  const handleUserSpecificRedirects = async () => {
    if (isCashBuy) {
      if (currentConditions.includes(`esign`)) {
        await postCartStatus({
          cartStatus: CART_STATUS.PENDING_ESIGNATURE,
        });
        history.push(ROUTE.ESIGN_VIEW);
        return true;
      }
    }
    return false;
  };
  const getPaymentFlow = (paymentMethod: PAYMENT_TYPE) => {
    const flows = paymentFlows[paymentMethod];

    if (isCashBuy) {
      if (subsidiesDepositAmount) return flows[PAYMENT_FLOWS.SUBSIDIES];
      if (isIDealEnabled && isIDealPaymentMode)
        return flows[PAYMENT_FLOWS.IDEAL];
    }

    return flows[PAYMENT_FLOWS.DEFAULT];
  };

  const handleContinueToOrder = async () => {
    setLoading(true);
    const userShouldBeRedirected = await handleUserSpecificRedirects();
    if (userShouldBeRedirected) return;

    const handler = getPaymentFlow(paymentType);
    handler && void handler();
  };

  const defaultBillingAddress =
    paymentAddress || userData.profile?.defaultBillingAddress;
  const defaultShippingAddress =
    shippingAddress || userData.profile?.defaultShippingAddress;

  const showCrossBorderMsg = crossBorderValidation(
    currentConditions.includes(`extra_only`),
    marketId,
    defaultBillingAddress,
    defaultShippingAddress,
  );

  if (showCrossBorderMsg) {
    history.push(ROUTE.PERSONAL_DETAILS);
  }

  useTrackingDelivery(`order_overview`);

  const isFrozenCartAndLoaModeNotChosen =
    cartStatus.isFrozen && activePaymentMode !== PAYMENT_MODE.LOA;
  const isDisabledButtonRow = (): boolean =>
    isFrozenCartAndLoaModeNotChosen ||
    !isTermsAndConditionsValid ||
    disabledByAgentLeasingCheck ||
    isPaymentModeStatusUpdating ||
    orderError.is(LeasingOrderConflictError);

  if (loading) {
    return (
      <>
        <LoadingPage />
      </>
    );
  }
  if (orderError.showErrorPage) {
    const stockError = orderError.is(StockReservePeriodExpiredError);

    return (
      <ErrorMessage
        stockError={stockError}
        showRefreshButton={!stockError}
        errorMessage={orderError.error?.message}
      />
    );
  }
  const {t} = useTranslations(translations);

  return (
    <div className={styles[`${orderOverviewBaseClass}`]}>
      {pcpPaymentResponse &&
        pcpPaymentResponse.code !== `200` &&
        showPCPErrorNotific && (
          <Notification
            className={styles[`${orderOverviewBaseClass}__error-notification`]}
            text={pcpPaymentResponse?.message}
            label={t(`pcp.notification.error`)}
            closeButton={{
              ariaLabel: t(`pcp.notification.close`),
              onClick: () => setShowPCPErrorNotific(false),
            }}
            variant="error"
          />
        )}
      <Notifications orderError={orderError} paymentFailed={failedPayment} />
      <div className={styles[`${orderOverviewBaseClass}__content`]}>
        <div className={styles[`${orderOverviewBaseClass}__container`]}>
          <OrderDetails />
        </div>
        <div
          className={`${styles[`${orderOverviewBaseClass}__container`]} ${
            styles[`${orderOverviewBaseClass}__container--left`]
          }`}
        >
          <OrderSummary showPaymentCalculator={false} />
          {subsidiesDepositAmount && (
            <DepositContainer depositAmount={subsidiesDepositAmount} />
          )}
          <PaymentSummary
            availablePaymentModes={paymentModesFiltered}
            isIDealEnabled={isIDealEnabled}
            isPaymentModeStatusUpdating={isPaymentModeStatusUpdating}
            setPaymentModeStatusUpdating={setPaymentModeStatusUpdating}
          />
          <TermsConditions onChange={setIsTermsAndConditionsValid} />
          <ButtonsRow
            handleContinueToOrder={handleContinueToOrder}
            continueDisabled={isDisabledButtonRow()}
          />
        </div>
      </div>
    </div>
  );
};
